def to_wire_workflow_value_kind(value: native.WorkflowValueKind) -> dict[str, Any]:
    if isinstance(value, native.WorkflowValueLiteral):
        return {"literal": to_wire_value(value.value)}
    if isinstance(value, native.WorkflowValueObject):
        return {"object": to_wire_workflow_object(value.value)}
    if isinstance(value, native.WorkflowValueArray):
        return {"array": to_wire_workflow_array(value.value)}
    if isinstance(value, native.WorkflowValueTemplate):
        return {"template": to_wire_workflow_text(value.value)}
    if isinstance(value, native.WorkflowValueInput):
        return {"input": to_wire_workflow_path_source(value.value)}
    if isinstance(value, native.WorkflowValueSignal):
        return {"signal": to_wire_workflow_path_source(value.value)}
    if isinstance(value, native.WorkflowValueStepOutput):
        return {"step_output": to_wire_workflow_step_output_source(value.value)}
    if isinstance(value, native.WorkflowValueStepInput):
        return {"step_input": to_wire_workflow_step_input_source(value.value)}
    return {}


def from_wire_workflow_value_kind(value: Any) -> native.WorkflowValueKind:
    case = value.WhichOneof("kind")
    if case == "literal":
        return native.WorkflowValueLiteral(value=from_wire_value(value.literal))
    if case == "object":
        return native.WorkflowValueObject(value=from_wire_workflow_object(value.object))
    if case == "array":
        return native.WorkflowValueArray(value=from_wire_workflow_array(value.array))
    if case == "template":
        return native.WorkflowValueTemplate(
            value=from_wire_workflow_text(value.template)
        )
    if case == "input":
        return native.WorkflowValueInput(
            value=from_wire_workflow_path_source(value.input)
        )
    if case == "signal":
        return native.WorkflowValueSignal(
            value=from_wire_workflow_path_source(value.signal)
        )
    if case == "step_output":
        return native.WorkflowValueStepOutput(
            value=from_wire_workflow_step_output_source(value.step_output)
        )
    if case == "step_input":
        return native.WorkflowValueStepInput(
            value=from_wire_workflow_step_input_source(value.step_input)
        )
    return None
